// Регресс «готовность к выпуску 19.10.2026» — группа 8: регистрация.
// Запуск: QA_REG_MANUAL=1 (как RG-08/RG-09), иначе skip. Форма НЕ отправляется («שלח» не нажимается).
// Факты 19.10 (ac-status.md «Дополнение 19.10»): F-89 AC1 — пустые поля → «שלח» enabled=false; всё заполнено без галочки
// условий → enabled=false (app/F-89-empty-form.png, F-89-no-terms.png). F-43 AC3 — новый аккаунт 0501112088:
// «התחל את המסע שלך — עדיין לא השלמת אף תפילה…» на «בית» и «המסע שלי» (app/F-43-empty-new-account.png).
// Галочка — «אני מאשר את תנאי השימוש ואת מדיניות הפרטיות» (RG-02). RG-02 уже проверяет «без галочки на пустой форме» —
// здесь: пустые поля С галочкой и заполненная форма БЕЗ галочки. Кейсы: .qa/tests/readiness/RD-08-registration.md.
import { $$, expect, driver } from '@wdio/globals';
import { byText, byLabel, tapLabel, tapText, scrollToText } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, logout } from '../../helpers/app.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { goHome, counter, button } from '../_lib/readiness-1910.ts';

const TERMS = 'אני מאשר את תנאי השימוש ואת מדיניות הפרטיות';
const EMPTY_TITLE = 'התחל את המסע שלך';
const EMPTY_TEXT = 'עדיין לא השלמת אף תפילה. התפילות שתשלים יופיעו כאן.';

async function checked() {
  const el = await byLabel(TERMS);
  if (driver.isAndroid) return (await el.getAttribute('checked')) === 'true';
  const v = await el.getAttribute('value');
  return v === '1' || v === 'true' || (await el.isSelected().catch(() => false));
}
async function setTerms(on: boolean) {
  if ((await checked()) !== on) await (await byLabel(TERMS)).click();
  await driver.waitUntil(async () => (await checked()) === on, { timeout: 10000, timeoutMsg: `галочка не ${on ? 'отмечена' : 'снята'}` });
}
function fields() {
  return $$(driver.isAndroid ? 'android=new UiSelector().className("android.widget.EditText")' : '-ios class chain:**/XCUIElementTypeTextField');
}
async function sendEnabled() {
  await scrollToText('שלח');
  return (await button('שלח')).isEnabled();
}

describe('Готовность 19.10 — регистрация', () => {
  beforeEach(function () {
    if (process.env.QA_REG_MANUAL !== '1') skipWith(this, 'выход из аккаунта и регистрация — с человеком у телефона; запуск с QA_REG_MANUAL=1');
  });

  it('RD-08a «יצירת חשבון»: пустые обязательные поля (галочка отмечена) → «שלח» неактивна; всё заполнено без галочки → неактивна; с галочкой → активна (не нажимается) F-89 AC1 @manual-check', async function () {
    this.timeout(600000);
    try {
      await logout();
      await tapText('בואו נתחיל');
      await (await byText('כניסה דרך מספר נייד')).waitForDisplayed({ timeout: 20000 });
      const join = await byText('הצטרפו אלינו');
      if (await shown(join)) await join.click(); else await tapLabel('הצטרפו אלינו');
      await (await byText('יצירת חשבון')).waitForDisplayed({ timeout: 20000 });

      // 1. Все поля пустые, галочка отмечена → «שלח» неактивна.
      for (const f of await fields()) await f.clearValue();
      await setTerms(true);
      expect(await sendEnabled()).toBe(false);

      // 2. Заполнить все поля (имя, телефон, e-mail — по подписи поля, иначе по порядку), галочка снята → неактивна.
      const vals = { name: 'QA-AUTO רישום', phone: process.env.QA_REG_FORM_PHONE || '0501112099', email: 'qa.auto.form@example.com' };
      const order = [vals.name, vals.phone, vals.email];
      let i = 0;
      for (const f of await fields()) {
        const hint = `${await f.getAttribute(driver.isAndroid ? 'hint' : 'placeholderValue').catch(() => '')} ${await f.getAttribute(driver.isAndroid ? 'content-desc' : 'label').catch(() => '')}`;
        const v = /טלפון|נייד/.test(hint) ? vals.phone : /מייל|mail/i.test(hint) ? vals.email : /שם/.test(hint) ? vals.name : order[i] ?? vals.name;
        await f.click();
        await f.setValue(v);
        i++;
      }
      if (driver.isIOS) await driver.execute('mobile: hideKeyboard', {}).catch(() => {});
      await setTerms(false);
      expect(await sendEnabled()).toBe(false);
      // Положительный контроль: с галочкой кнопка активна (не нажимаем — аккаунт не создаётся).
      await setTerms(true);
      expect(await sendEnabled()).toBe(true);
      await setTerms(false);
    } finally {
      for (let k = 0; k < 4 && !(await isLoggedIn()); k++) {
        if (await shown(byText('בואו נתחיל'))) break;
        await driver.back().catch(() => {});
      }
      await ensureAppReady();   // вход тестовым аккаунтом из .qa/accounts.env (APP_ACCOUNT)
    }
  });

  it('RD-08b Новый аккаунт (после регистрации человеком, например RG-09): пустая история — «התחל את המסע שלך» + пояснение на «בית» и «המסע שלי», счётчики 0, «צפה בהכל» нет F-43 AC3 F-104 AC5 F-51 AC4 @manual-check @prod-safe', async function () {
    await goHome();
    if ((await counter('סה״כ תפילות')) !== 0) skipWith(this, 'в приложении не новый аккаунт (есть молитвы) — зарегистрируйте новый номер (RG-09) и запустите снова');
    expect(await counter('תפילות היום')).toBe(0);
    expect(await counter('ימים רצופים')).toBe(0);
    await scrollToText(EMPTY_TITLE);
    await expect(byText(EMPTY_TEXT)).toBeExisting();
    expect(await shown(byText('צפה בהכל'))).toBe(false);
    await tapText('המסע שלי');
    await scrollToText(EMPTY_TITLE);
    await expect(byText(EMPTY_TEXT)).toBeExisting();
  });
});
